def _find_travis_job(self, build, toxenv):
        """Given a build object, find the acceptance36 job"""
        for job in build["jobs"]:
            if job["config"]["env"]["TOXENV"] == toxenv:
                return job
        raise RuntimeError("Could not find job for %s" % toxenv)

